import{_ as e,o as d,c as a,ae as o}from"./chunks/framework.C4zpkcTP.js";const h=JSON.parse('{"title":"PaymentCallback & Status","description":"Field reference for PaymentCallback, PaymentStatusResult, Acknowledgement, CallbackRequest and the PaymentStatus enum.","frontmatter":{"title":"PaymentCallback & Status","description":"Field reference for PaymentCallback, PaymentStatusResult, Acknowledgement, CallbackRequest and the PaymentStatus enum."},"headers":[],"relativePath":"python-myanmar-payments/references/payment-callback.md","filePath":"python-myanmar-payments/references/payment-callback.md"}'),c={name:"python-myanmar-payments/references/payment-callback.md"};function r(s,t,n,l,u,y){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="paymentcallback-status" tabindex="-1">PaymentCallback &amp; Status <a class="header-anchor" href="#paymentcallback-status" aria-label="Permalink to &quot;PaymentCallback &amp; Status&quot;">​</a></h1><h2 id="paymentcallback" tabindex="-1">PaymentCallback <a class="header-anchor" href="#paymentcallback" aria-label="Permalink to &quot;PaymentCallback&quot;">​</a></h2><p>Returned by every gateway&#39;s <code>handle_callback()</code> (and AYA&#39;s <code>verify_redirect()</code>) once the signature is verified.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>order_id</code></td><td><code>str</code></td><td>Your order ID</td></tr><tr><td><code>status</code></td><td><code>PaymentStatus</code></td><td>The status mapped onto this package&#39;s statuses</td></tr><tr><td><code>gateway_status</code></td><td><code>str</code></td><td>The gateway&#39;s own status value, unmapped</td></tr><tr><td><code>gateway_reference</code></td><td><code>str | None</code></td><td>The gateway&#39;s ID for the payment</td></tr><tr><td><code>amount</code></td><td><code>str | None</code></td><td>The amount the gateway reports, exactly as it sent it</td></tr><tr><td><code>raw</code></td><td><code>Mapping[str, Any]</code></td><td>The verified payload, as plain Python values; JSON numbers are their exact text as <code>str</code>, never <code>float</code></td></tr><tr><td><code>acknowledgement</code></td><td><code>Acknowledgement</code></td><td>The response the gateway expects</td></tr><tr><td><code>is_successful()</code></td><td><code>bool</code></td><td><code>status is PaymentStatus.SUCCESSFUL</code></td></tr></tbody></table><p>Build one yourself to test your own fulfillment code, with keyword arguments: <code>PaymentCallback(order_id=..., status=..., gateway_status=..., gateway_reference=None, amount=None, raw=None, acknowledgement=None)</code>. <code>status</code> takes a <code>PaymentStatus</code> or its string value, and <code>acknowledgement</code> defaults to <code>Acknowledgement.default()</code>.</p><h2 id="acknowledgement" tabindex="-1">Acknowledgement <a class="header-anchor" href="#acknowledgement" aria-label="Permalink to &quot;Acknowledgement&quot;">​</a></h2><p>A frozen dataclass.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>int</code></td><td>HTTP status, <code>200</code> by default</td></tr><tr><td><code>body</code></td><td><code>str</code></td><td>Response body, e.g. KBZ Pay&#39;s <code>success</code>; empty by default</td></tr><tr><td><code>headers</code></td><td><code>Mapping[str, str]</code></td><td>Response headers, <code>{&quot;Content-Type&quot;: &quot;text/plain&quot;}</code> by default</td></tr></tbody></table><p><code>Acknowledgement.default()</code> is an empty <code>200</code> with <code>Content-Type: text/plain</code>. Write it with your framework&#39;s response class, see <a href="/python-myanmar-payments/callbacks.html#acknowledging">Acknowledging</a>.</p><h2 id="paymentstatusresult" tabindex="-1">PaymentStatusResult <a class="header-anchor" href="#paymentstatusresult" aria-label="Permalink to &quot;PaymentStatusResult&quot;">​</a></h2><p>Returned by <code>kbz.status()</code>, <code>aya.status()</code> and <code>yoma.status()</code>. A frozen dataclass.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>order_id</code></td><td><code>str | None</code></td><td>Your order ID; <code>None</code> for Yoma, which returns only the reference</td></tr><tr><td><code>status</code></td><td><code>PaymentStatus</code></td><td>The mapped status</td></tr><tr><td><code>gateway_status</code></td><td><code>str</code></td><td>The gateway&#39;s own status value</td></tr><tr><td><code>gateway_reference</code></td><td><code>str | None</code></td><td>The gateway&#39;s ID for the payment</td></tr><tr><td><code>amount</code></td><td><code>str | None</code></td><td>The amount the gateway reports</td></tr><tr><td><code>raw</code></td><td><code>Mapping[str, Any]</code></td><td>The gateway&#39;s response</td></tr><tr><td><code>is_successful()</code></td><td><code>bool</code></td><td><code>status is PaymentStatus.SUCCESSFUL</code></td></tr></tbody></table><h2 id="callbackrequest" tabindex="-1">CallbackRequest <a class="header-anchor" href="#callbackrequest" aria-label="Permalink to &quot;CallbackRequest&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Member</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>CallbackRequest(body=None, headers=None, query=None)</code></td><td><code>CallbackRequest</code></td><td>From the raw parts: the body as <code>bytes</code> or <code>str</code>, the headers as a mapping or <code>(name, value)</code> pairs, the query string as <code>str</code>, <code>bytes</code>, a mapping or pairs (Django&#39;s <code>QueryDict</code>, Werkzeug&#39;s <code>MultiDict</code> and Starlette&#39;s <code>QueryParams</code> work too)</td></tr><tr><td><code>CallbackRequest.from_json(payload, headers=None)</code></td><td><code>CallbackRequest</code></td><td>From a decoded payload, encoded as a JSON body with <code>Content-Type: application/json</code>; <code>Decimal</code> values are written as strings</td></tr><tr><td><code>raw_body</code></td><td><code>bytes</code></td><td>The raw body, exactly as received</td></tr><tr><td><code>body</code></td><td><code>str</code></td><td>The raw body, decoded as UTF-8</td></tr><tr><td><code>headers</code></td><td><code>Mapping[str, str]</code></td><td>Headers with lowercase names; repeated headers joined with <code>, </code></td></tr><tr><td><code>query</code></td><td><code>Mapping[str, str]</code></td><td>Query string values (the first of each)</td></tr><tr><td><code>header(name)</code></td><td><code>str | None</code></td><td>One header, case-insensitively</td></tr><tr><td><code>parsed_body()</code></td><td><code>dict[str, Any]</code></td><td>The body decoded as JSON or a form; JSON numbers keep their exact text as <code>str</code></td></tr><tr><td><code>input()</code></td><td><code>dict[str, Any]</code></td><td>The body merged over the query string</td></tr><tr><td><code>query_input()</code></td><td><code>dict[str, Any]</code></td><td>The query string merged over the body</td></tr></tbody></table><h2 id="paymentstatus" tabindex="-1">PaymentStatus <a class="header-anchor" href="#paymentstatus" aria-label="Permalink to &quot;PaymentStatus&quot;">​</a></h2><p><code>class PaymentStatus(str, Enum)</code>: members are strings, so they compare equal to their values and <code>str(status)</code> is the value.</p><table tabindex="0"><thead><tr><th>Member</th><th>Value</th></tr></thead><tbody><tr><td><code>PaymentStatus.SUCCESSFUL</code></td><td><code>successful</code></td></tr><tr><td><code>PaymentStatus.PENDING</code></td><td><code>pending</code></td></tr><tr><td><code>PaymentStatus.FAILED</code></td><td><code>failed</code></td></tr><tr><td><code>PaymentStatus.CANCELED</code></td><td><code>canceled</code></td></tr><tr><td><code>PaymentStatus.EXPIRED</code></td><td><code>expired</code></td></tr><tr><td><code>PaymentStatus.UNKNOWN</code></td><td><code>unknown</code></td></tr></tbody></table><p><code>list(PaymentStatus)</code> lists every status. <code>status.is_final()</code> is <code>False</code> for <code>PENDING</code> and <code>UNKNOWN</code>. <code>resolve_status(statuses, gateway_status)</code> maps a trimmed gateway value through a <code>dict</code> and returns <code>PaymentStatus.UNKNOWN</code> when it is not listed.</p>',18)])])}const m=e(c,[["render",r]]);export{h as __pageData,m as default};
